let currentAgent=agents.find(agent=>agent.code===params.get("code"))||agents[0], drawerStep=1;
function renderAgents(){const q=$('#agent-search')?.value.trim().toLowerCase()||'',f=$('#agent-filter')?.value||'all';const list=agents.filter(a=>(f==='all'||a.status===f)&&(!q||(a.name+a.code).toLowerCase().includes(q)));$('#agent-count').textContent=`${list.length} 个 Agent`;$('#agent-tbody').innerHTML=list.map(a=>`<tr><td><div class="agent-name"><div class="agent-mark">${a.name[0]}</div><div><b>${escapeHtml(a.name)}</b><small>${escapeHtml(a.code)}</small></div></div></td><td>${a.type==='supervisor'?'<span class="badge blue">主 Agent</span>':'普通 Agent'}</td><td>${escapeHtml(a.model)}</td><td>${statusBadge(a.status)}</td><td>${escapeHtml(a.updated)}</td><td><button class="link" data-agent-code="${escapeHtml(a.code)}">打开</button></td></tr>`).join('')||'<tr><td colspan="6" class="empty">没有匹配的 Agent</td></tr>';$$('[data-agent-code]').forEach(b=>b.onclick=()=>openAgent(b.dataset.agentCode))}
function renderSubagents(){const pool=agents.filter(a=>a.code!==currentAgent.code&&a.type==='normal');$('#subagent-grid').innerHTML=pool.map(a=>`<label class="subagent-card ${currentAgent.subs.includes(a.name)?'selected':''}"><input type="checkbox" value="${escapeHtml(a.name)}" ${currentAgent.subs.includes(a.name)?'checked':''}><h4>${escapeHtml(a.name)}</h4><p>${escapeHtml(a.desc)}</p><div class="sub" style="margin-top:8px">${escapeHtml(a.code)}</div></label>`).join('');$$('#subagent-grid input').forEach(i=>i.onchange=()=>i.closest('.subagent-card').classList.toggle('selected',i.checked))}
if (pageName === 'agents') {
  on('#agent-search', 'input', renderAgents); on('#agent-filter', 'change', renderAgents); renderAgents();
}
if (pageName.startsWith('agent-') && pageName !== 'agent-create') {
  $('#detail-name').textContent = currentAgent.name; $('#detail-code').textContent = currentAgent.code; $('#detail-mark').textContent = currentAgent.name[0];
  $$('[data-agent-tab]').forEach(anchor => anchor.href = pageUrl('agent-' + anchor.dataset.agentTab + '.html', {code: currentAgent.code}));
  if ($('#edit-name')) {
    $('#edit-name').value = currentAgent.name; $('#edit-type').value = currentAgent.type; $('#edit-model').value = currentAgent.model;
  }
  if ($('#subagent-grid')) renderSubagents();
  on('#save-config', 'click', () => {
    currentAgent.name = $('#edit-name').value.trim() || currentAgent.name; currentAgent.type = $('#edit-type').value; currentAgent.model = $('#edit-model').value;
    $('#detail-name').textContent = currentAgent.name; $('#detail-mark').textContent = currentAgent.name[0]; saveDemoState(); toast('配置草稿已保存');
  });
  on('#save-subs', 'click', () => {currentAgent.subs = $$('#subagent-grid input:checked').map(input=>input.value); saveDemoState(); toast('SubAgent 关系已保存为草稿');});
  on('#publish-btn', 'click', () => {currentAgent.status='published'; currentAgent.updated='刚刚'; saveDemoState(); toast('已发布新版本 v4');});
}

on('#run-test','click',()=>{const input=$('#debug-input').value.trim();if(!input){toast('请输入测试问题');return}const btn=$('#run-test');btn.disabled=true;$('#chat-body').insertAdjacentHTML('beforeend',`<div class="bubble user">${input.replace(/[<>&]/g,c=>({'<':'&lt;','>':'&gt;','&':'&amp;'}[c]))}</div>`);$('#debug-input').value='';const steps=[['构建上下文','加载Agent版本和当前会话'],['主 Agent 判断','拆分为数据查询与知识检索'],['数据查询 Agent','调用经营数据查询工具'],['知识检索 Agent','检索相关业务说明'],['主 Agent 汇总','合并结果并生成结论']];$('#trace-body').className='';$('#trace-body').innerHTML=steps.map((s,i)=>`<div class="trace-step" id="trace-${i}"><b>${s[0]}</b><span>${s[1]}</span></div>`).join('');let i=0;const next=()=>{if(i>0)$('#trace-'+(i-1)).className='trace-step done';if(i<steps.length){$('#trace-'+i).className='trace-step running';i++;setTimeout(next,520);return}$('#chat-body').insertAdjacentHTML('beforeend','<div class="bubble agent"><b>测试结果</b><br>销售下滑主要集中在华东区域。初步原因包括重点门店客流下降和两个主力品类缺货。建议先核对门店库存与促销执行记录，再确认是否需要调整补货计划。</div>');$('#chat-body').scrollTop=$('#chat-body').scrollHeight;btn.disabled=false;toast('测试运行完成')};next()});
function updateToolGroupState(group){const items=$$(`input[data-tool-group="${group}"]`),checked=items.filter(i=>i.checked).length,master=$(`[data-tool-group-all="${group}"]`);master.checked=items.length>0&&checked===items.length;master.indeterminate=checked>0&&checked<items.length}
function updateDrawer(){$$('.drawer-step').forEach(s=>s.classList.toggle('active',Number(s.dataset.drawerStep)===drawerStep));$$('.stepper-item').forEach((s,i)=>{s.classList.toggle('active',i+1===drawerStep);s.classList.toggle('done',i+1<drawerStep)});$('#drawer-prev').textContent=drawerStep===1?'取消':'上一步';$('#drawer-next').textContent=drawerStep===3?'创建并调试':'下一步';const isSup=$('input[name="new-type"]:checked').value==='supervisor';$('#collab-normal').style.display=isSup?'none':'block';$('#collab-supervisor').style.display=isSup?'block':'none';if(!$('#new-sub-options').children.length)$('#new-sub-options').innerHTML=agents.filter(a=>a.type==='normal').map(a=>`<label class="option"><input type="checkbox" value="${escapeHtml(a.name)}"><div><b>${escapeHtml(a.name)}</b><span>${escapeHtml(a.desc)}</span></div></label>`).join('')}
if(pageName==='agent-create'){
$$('[data-tool-group-all]').forEach(master=>master.onchange=()=>{$$(`input[data-tool-group="${master.dataset.toolGroupAll}"]`).forEach(item=>item.checked=master.checked);updateToolGroupState(master.dataset.toolGroupAll)});$$('input[data-tool-group]').forEach(item=>item.onchange=()=>updateToolGroupState(item.dataset.toolGroup));['data','knowledge','output'].forEach(updateToolGroupState);
$('#drawer-prev').onclick=()=>{if(drawerStep===1)navigate('agents.html');else{drawerStep--;updateDrawer()}};$('#drawer-next').onclick=()=>{if(drawerStep===1&&!$('#new-agent-name').value.trim()){const e=$('#name-error');e.textContent='请输入Agent名称';e.style.color='#dc2626';$('#new-agent-name').focus();return}if(drawerStep<3){drawerStep++;updateDrawer();return}const name=$('#new-agent-name').value.trim(),type=$('input[name="new-type"]:checked').value,subs=type==='supervisor'?$$('#new-sub-options input:checked').map(i=>i.value):[],tools=$$('input[data-tool-group]:checked').map(i=>i.value);const a={code:'agt_01J'+Math.random().toString(36).slice(2,8).toUpperCase(),name,desc:$('#new-agent-desc').value.trim()||'尚未填写说明',type,model:$('#new-agent-model').value,status:'draft',updated:'刚刚',subs,tools};agents.unshift(a);saveDemoState();openAgent(a.code,'debug')};$$('input[name="new-type"]').forEach(i=>i.onchange=updateDrawer);
updateDrawer();
}
